mapper.sql:
WHERE g.deleted_at IS NULL
  AND creator.deleted_at IS NULL

    AND (g.group_name LIKE #{keywordPattern} ESCAPE '!'
    OR g.description LIKE #{keywordPattern} ESCAPE '!')


    AND r.province_name = #{provinceName}


    AND r.district_name = #{districtName}


    AND r.town_name = #{townName}


    AND sg.status = #{status}

mapper.update:
UPDATE small_group
SET status = #{nextStatus}
WHERE small_group_id = #{smallGroupId}
  AND status = #{currentStatus}
